entries[17720] = { ["name"] = "Bauplan: Schneemeister 9000", ["text"] = "Benötigt Ingenieurskunst (190)\nBenutzen: Lehrt Euch die Herstellung eines Schneemeister 9000.\nVerkaufspreis:\nSchneemeister 9000\nBenötigt Ingenieurskunst (190)\nBenutzen: Ermöglicht einem erfahrenen Ingenieur, Wasser in einen Schneeball zu verwandeln. Der Schneemeister benötigt einen Tag, um genügend Kälte aufzubauen, um einen weiteren Schneeball einzufrieren. (1 Tag Abklingzeit)\nVerkaufspreis:\nBenötigt Mithrilbarren (8), Gyrochronatom (4), Schneeball (4), Frostöl" }
