entries[18582] = { ["name"] = "Die Zwillingsklingen von Azzinoth", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nEinhändig Schwert\n148 - 155 Schaden Tempo 1.50 + 40 - 60 Schattenschaden + 40 - 60 Arkanschaden\n(167.67 Schaden pro Sekunde)\n+75 Beweglichkeit\n+100 Ausdauer\n+150 Intelligenz\n+100 Arkanwiderstand\n+100 Schattenwiderstand\nBenötigt Stufe 70\nAnlegen: Aufgezehrt von Illidans Zorn: 1400 Angriffskraftbonus gegen Dämonen. 20% Bonuschance auf Treffer. 30% Nahkampfgeschwindigkeit.\nBenutzen: Trennt die Zwillingsklingen, bildet zwei einzelne Kriegsgleven.\nVerkaufspreis:" }
entries[18583] = { ["name"] = "Kriegsgleve von Azzinoth (rechts)", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nEinhändig Schwert\n77 - 85 Schaden Tempo 1.00 + 30 - 60 Arkanschaden\n(126.00 Schaden pro Sekunde)\n+40 Beweglichkeit\n+50 Ausdauer\n+60 Intelligenz\n+60 Arkanwiderstand\n+50 Schattenwiderstand\nBenötigt Stufe 70\nBenutzen: Vereinigt die Zwillings-Kriegsgleven von Azzinoth, bildet die Zwillingsklingen von Azzinoth.\nVerkaufspreis:" }
