entries[18592] = { ["name"] = "Pläne: Sulfuronhammer", ["text"] = "Einzigartig\nBenötigt Schmiedekunst (300)\nBenutzen: Lehrt Euch die Herstellung eines Sulfuronhammers.\nVerkaufspreis:\nSulfuronhammer\nWird beim Anlegen gebunden\nZweihändig Streitkolben\n176 - 295 Schaden Tempo 3.70\n(63.65 Schaden pro Sekunde)\nHaltbarkeit 120 / 120\nBenötigt Stufe 60\nTrefferchance: Schleudert eine glühende Kugel, die 83 bis 101 Feuerschaden sowie zusätzlich 8 Sek. lang insgesamt 16 Schaden verursacht.\nVerkaufspreis:\nBenötigt Sulfuronblock (8), Dunkeleisenbarren (20), Arkanitbarren (50), Essenz des Feuers (25), Blut des Berges (10), Lavakern (10), Feuerkern (10)" }
