entries[18606] = { ["name"] = "Schlachtstandarte der Allianz", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Platziert eine Schlachtstandarte mit 1500 Gesundheit, die die maximale Gesundheit aller Gruppenmitglieder, die sich im Umkreis von 45 Metern der Schlachtstandarte befinden, um 15% erhöht. Hält 2 Min. lang an. Die Schlachtstandarte kann nur auf einem PvP-Schlachtfeld verwendet werden. (10 Min Abklingzeit)" }
