entries[18608] = { ["name"] = "Segnung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nZweihändig Stab\n134 - 222 Schaden Tempo 3.00\n(59.33 Schaden pro Sekunde)\n+10 Ausdauer\n+31 Intelligenz\n+12 Willenskraft\n+20 Schattenwiderstand\nHaltbarkeit 120 / 120\nKlassen: Priester\nBenötigt Stufe 60\nAnlegen: Erhöht die kritische Zaubertrefferwertung um 28.\nBenutzen: Ruft nach Bannfluch. (30 Min Abklingzeit)\nAnlegen: Erhöht durch sämtliche Zauber und magische Effekte verursachte Heilung um bis zu 106 und den verursachten Schaden um bis zu 36." }
entries[18609] = { ["name"] = "Bannfluch", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nZweihändig Stab\n134 - 222 Schaden Tempo 3.00\n(59.33 Schaden pro Sekunde)\n+22 Ausdauer\n+31 Intelligenz\n+20 Schattenwiderstand\nHaltbarkeit 120 / 120\nKlassen: Priester\nBenötigt Stufe 60\nBenutzen: Ruft nach Segnung. (30 Min Abklingzeit)\nAnlegen: Stellt alle 5 Sek. 7 Mana wieder her.\nAnlegen: Erhöht durch Schattenzauber und Schatteneffekte zugefügten Schaden um bis zu 69." }
