entries[18642] = { ["name"] = "Jainas Autogramm", ["text"] = "Questgegenstand\nEinzigartig\n\"Sei stark Randis und strebe danach der Held zu werden, der dir vorherbestimmt wurde zu sein. -- Lady Jaina Prachtmeer\"" }
entries[18643] = { ["name"] = "Cairnes Hufabdruck", ["text"] = "Questgegenstand\nEinzigartig\n\"Höre auf die Geister, junger Grunz. Denn nur von ihnen erfährt der wahre Held seine Berufung. -- Cairne Bluthuf\"" }
entries[18645] = { ["name"] = "Gnomischer Alarm-O-Bot", ["text"] = "Benötigt Ingenieurskunst (265)\nBenutzen: Erschafft für 10 Minuten einen Alarm-O-Bot, der in regelmäßigen Abständen einen Impuls aussendet, welcher getarnte oder unsichtbare Einheiten aufspürt. (10 Min Abklingzeit)\nVerkaufspreis:" }
