entries[18647] = { ["name"] = "Bauplan: Rotes Feuerwerk", ["text"] = "Benötigt Ingenieurskunst (150)\nBenutzen: Lehrt Euch die Herstellung von rotem Feuerwerk.\nVerkaufspreis:\nRotes Feuerwerk\nBenutzen: Schießt ein Feuerwerk in die Luft, das in tausend rote Sterne explodiert.\nVerkaufspreis:\nBenötigt Schweres Sprengpulver , Schweres Leder" }
entries[18648] = { ["name"] = "Bauplan: Grünes Feuerwerk", ["text"] = "Benötigt Ingenieurskunst (150)\nBenutzen: Lehrt Euch die Herstellung von grünem Feuerwerk.\nVerkaufspreis:\nGrünes Feuerwerk\nBenutzen: Schießt ein Feuerwerk in die Luft, das in tausend grüne Sterne explodiert.\nVerkaufspreis:\nBenötigt Schweres Sprengpulver , Schweres Leder" }
entries[18649] = { ["name"] = "Bauplan: Blaues Feuerwerk", ["text"] = "Benötigt Ingenieurskunst (150)\nBenutzen: Lehrt Euch die Herstellung von blauem Feuerwerk.\nVerkaufspreis:\nBlaues Feuerwerk\nBenutzen: Schießt ein Feuerwerk in die Luft, das in tausend blaue Sterne explodiert.\nVerkaufspreis:\nBenötigt Schweres Sprengpulver , Schweres Leder" }
entries[18650] = { ["name"] = "Bauplan: EZ-Thro-Dynamit II", ["text"] = "Benötigt Ingenieurskunst (200)\nBenutzen: Lehrt Euch die Herstellung von EZ-Thro-Dynamit II.\nVerkaufspreis:\nEZ-Thro-Dynamit II\nBenötigt Stufe 30\nBenutzen: Fügt 213 bis 287 Feuerschaden in einem Umkreis von 5 Metern zu (sollte es das Ziel treffen; es gelten Beschränkungen). (1 Min Abklingzeit)\n\"Das Dynamit für jedermann, das selten* in der Hand hochgeht, mit mehr als der doppelten Sprengkraft von einfachem EZ-Thro.\"\nVerkaufspreis:\nBenötigt Robustes Sprengpulver , Magiestoff (2)" }
entries[18651] = { ["name"] = "Bauplan: Echtsilberumwandler", ["text"] = "Benötigt Ingenieurskunst (260)\nBenutzen: Lehrt Euch die Herstellung eines Echtsilberumwandlers.\nVerkaufspreis:\nEchtsilberumwandler\nVerkaufspreis:\nBenötigt Echtsilberbarren (2), Elementarerde (2), Elementarluft" }
entries[18652] = { ["name"] = "Bauplan: Gyrofrosteisreflektor", ["text"] = "Benötigt Ingenieurskunst (260)\nBenutzen: Lehrt Euch die Herstellung eines Gyrofrosteisreflektors.\nVerkaufspreis:\nGyrofrosteisreflektor\nWird beim Anlegen gebunden\nSchmuck\n+15 Frostwiderstand\nBenötigt Stufe 47\nBenötigt Ingenieurskunst (260)\nBenutzen: Reflektiert Frostzauber für 5 Sek. zurück auf den Zaubernden. Es besteht die Chance, dass dem Effekt widerstanden wird, wenn der Zaubernde über Stufe 60 ist. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Thoriumapparat (6), Echtsilberumwandler (2), Blauer Saphir (2), Essenz des Feuers (4), Frostöl (2), Eiskappe (4)" }
entries[18653] = { ["name"] = "Bauplan: Goblinüberbrückungskabel XL", ["text"] = "Benötigt Ingenieurskunst (265)\nBenötigt Gobliningenieur\nBenutzen: Lehrt Euch die Herstellung von Goblinüberbrückungskabeln XL.\nVerkaufspreis:\nGoblinüberbrückungskabel XL\nBenötigt Ingenieurskunst (265)\nBenutzen: Mit Überbrückungskabeln kann man manchmal einen toten Spieler ins Leben zurückrufen. Kann nicht im Kampf verwendet werden. (30 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Thoriumapparat (2), Echtsilberumwandler (2), Verschmorte Verkabelung (2), Eisenweberseide (2), Sternrubin (2)" }
entries[18654] = { ["name"] = "Bauplan: Gnomischer Alarm-O-Bot", ["text"] = "Benötigt Ingenieurskunst (265)\nBenötigt Gnomeningenieur\nBenutzen: Lehrt Euch die Herstellung eines Alarm-O-Bots.\nVerkaufspreis:\nGnomischer Alarm-O-Bot\nBenötigt Ingenieurskunst (265)\nBenutzen: Erschafft für 10 Minuten einen Alarm-O-Bot, der in regelmäßigen Abständen einen Impuls aussendet, welcher getarnte oder unsichtbare Einheiten aufspürt. (10 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Thoriumbarren (4), Thoriumapparat (2), Unverwüstliches Leder (4), Sternrubin , Verschmorte Verkabelung" }
entries[18655] = { ["name"] = "Bauplan: Großer Rekombobulator", ["text"] = "Benötigt Ingenieurskunst (275)\nBenutzen: Lehrt Euch die Herstellung eines großen Rekombobulator.\nVerkaufspreis:\nGroßer Rekombobulator\nSchmuck\nBenötigt Ingenieurskunst (275)\nBenutzen: Stellt 375 bis 625 Gesundheit und Mana eines freundlichen Ziels wieder her und versucht, jegliche Verwandlungseffekte auf ihm zu bannen. Verringerte Wirksamkeit gegen Verwandlungseffekte von Zaubernden der Stufe 61 und höher. (5 Min Abklingzeit)\n10 Aufladungen\nVerkaufspreis:\nBenötigt Thoriumröhre (2), Echtsilberumwandler , Runenstoff (2)" }
entries[18656] = { ["name"] = "Bauplan: Mächtige Zephyriumladung", ["text"] = "Benötigt Ingenieurskunst (275)\nBenutzen: Lehrt Euch die Herstellung von mächtigen Zephyriumladungen.\nVerkaufspreis:\nMächtige Zephyriumladung\nBenötigt Ingenieurskunst (275)\nBenutzen: Sprengt fast jede fest verschlossene Tür oder Truhe auf.\nVerkaufspreis:\nBenötigt Thoriumapparat (2), Dichtes Sprengpulver (3), Unverwüstliches Leder (2), Erfrischendes Quellwasser" }
entries[18657] = { ["name"] = "Bauplan: Hyperstrahlender Flammenreflektor", ["text"] = "Benötigt Ingenieurskunst (290)\nBenutzen: Lehrt Euch die Herstellung eines hyperstrahlenden Flammenreflektors.\nVerkaufspreis:\nHyperstrahlender Flammenreflektor\nWird beim Anlegen gebunden\nSchmuck\n+18 Feuerwiderstand\nBenötigt Stufe 53\nBenötigt Ingenieurskunst (290)\nBenutzen: Reflektiert Feuerzauber für 5 Sek. zurück auf den Zaubernden. Es besteht die Chance, dass dem Effekt widerstanden wird, wenn der Zaubernde über Stufe 60 ist. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Dunkeleisenbarren (4), Echtsilberumwandler (3), Essenz des Wassers (6), Sternrubin (4), Azerothischer Diamant (2)" }
entries[18658] = { ["name"] = "Bauplan: Ultrablendender Schattenreflektor", ["text"] = "Benötigt Ingenieurskunst (300)\nBenutzen: Lehrt Euch die Herstellung eines ultrablendenden Schattenreflektors.\nVerkaufspreis:\nUltrablendender Schattenreflektor\nWird beim Anlegen gebunden\nSchmuck\n+20 Schattenwiderstand\nBenötigt Stufe 55\nBenötigt Ingenieurskunst (300)\nBenutzen: Reflektiert Schattenzauber für 5 Sek. zurück auf den Zaubernden. Es besteht die Chance, dass dem Effekt widerstanden wird, wenn der Zaubernde über Stufe 60 ist. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Dunkeleisenbarren (8), Echtsilberumwandler (4), Essenz des Lebens (6), Essenz des Untodes (4), Azerothischer Diamant (2), Großer Opal (2)" }
